class CarBuilder {
  private make = '';
  private model = '';
  withMake(make: string) { this.make = make; return this; }
  withModel(model: string) { this.model = model; return this; }
  build() { return new Car(this.make, this.model); }
}
const car = new CarBuilder().withMake('Ford').withModel('Focus').build();

