/* Version A */
class Widget {
  constructor(public name = '', public color = '') {}
  setName(name: string) { this.name = name; return this; }
  setColor(color: string) { this.color = color; return this; }
}
const a = new Widget().setName('Box').setColor('Red');

/* Version B */
class WidgetV2 {
  constructor(public readonly name: string, public readonly color: string) {}
}
class WidgetBuilder {
  private name = '';
  private color = '';
  withName(name: string) { this.name = name; return this; }
  withColor(color: string) { this.color = color; return this; }
  build() { return new WidgetV2(this.name, this.color); }
}
const b = new WidgetBuilder().withName('Box').withColor('Red').build();
